import sys

def main():
    data = sys.stdin.read().split()
    q = int(data[0])
    cnt = {}
    bits = [0] * 30
    total = 0
    out = []
    p = 1
    for _ in range(q):
        t = int(data[p]); x = int(data[p + 1]); p += 2
        if t == 1:
            cnt[x] = cnt.get(x, 0) + 1
            total += 1
            b = 0
            y = x
            while y:
                if y & 1:
                    bits[b] += 1
                y >>= 1
                b += 1
        elif t == 2:
            c = cnt.pop(x, 0)
            if c:
                total -= c
                b = 0
                y = x
                while y:
                    if y & 1:
                        bits[b] -= c
                    y >>= 1
                    b += 1
        else:
            s = 0
            for b in range(30):
                if (x >> b) & 1:
                    s += (total - bits[b]) << b
                else:
                    s += bits[b] << b
            out.append(s)
    print('\n'.join(map(str, out)))

