        in.nextToken();
        int q = (int) in.nval;
        int[] types = new int[q];
        long[] xs = new long[q];
        for (int i = 0; i < q; i++) {
            in.nextToken(); types[i] = (int) in.nval;
            in.nextToken(); xs[i] = (long) in.nval;
        }
        long[] res = xorWorld(types, xs);
